package app.snapcare.dispenserdemo

import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test

/**
 * This app's pairing crypto, checked against the firmware's own output.
 *
 *     ./gradlew :app:testDebugUnitTest
 *
 * `vectors.json` is generated by `../webapp_kit/tools/make_vectors.py`, which
 * imports the actual firmware modules and is copied in at build time. So these
 * are not this code agreeing with itself — they are this code agreeing with the
 * Python running on the Raspberry Pi.
 *
 * That matters more here than it looks. There are four implementations of this
 * derivation sharing no code, and the failure mode of a disagreement is not an
 * exception: it is a schedule that seals fine, uploads fine, downloads fine and
 * then does not open, with the dispenser logging nothing because a failed open
 * is indistinguishable from a message meant for somebody else. Nothing but a
 * shared vector catches that.
 *
 * These run on the JVM, not on a device, which is why `Pairing` deliberately
 * uses neither `android.util.Base64` nor `org.json`.
 */
class VectorsTest {

    private val vectors: JSONObject by lazy {
        val stream = javaClass.classLoader!!.getResourceAsStream("vectors.json")
            ?: error("vectors.json is not on the test classpath — run `make vectors` in ../webapp_kit/")
        JSONObject(stream.bufferedReader().readText())
    }

    private fun hex(raw: ByteArray) = raw.joinToString("") { "%02x".format(it) }
    private fun unhex(text: String) = ByteArray(text.length / 2) {
        text.substring(it * 2, it * 2 + 2).toInt(16).toByte()
    }

    private fun envelopeOf(json: JSONObject) =
        Pairing.Envelope(json.getInt("rev"), json.getString("iv"), json.getString("ct"))

    // ── the code ────────────────────────────────────────────────────────────

    @Test
    fun `claim normalisation matches the firmware character for character`() {
        val cases = vectors.getJSONObject("claim").getJSONArray("normalise")
        for (index in 0 until cases.length()) {
            val case = cases.getJSONObject(index)
            val expected = case.getString("expect").ifEmpty { null }
            assertEquals(
                case.optString("why", case.getString("input")),
                expected,
                Pairing.normaliseClaim(case.getString("input")),
            )
        }
    }

    @Test
    fun `a short code is refused rather than padded`() {
        assertNull(Pairing.normaliseClaim("6V9F59QK6"))
        try {
            Pairing.deviceId("6V9F59QK6")
            fail("a nine-character code must not derive anything")
        } catch (_: Pairing.InvalidClaimException) {
        }
    }

    @Test
    fun `the display form is hyphenated and derives identically`() {
        val claim = vectors.getJSONObject("claim")
        assertEquals(claim.getString("formatted"), Pairing.formatClaim(claim.getString("sample")))
        assertEquals(
            Pairing.deviceId(claim.getString("sample")),
            Pairing.deviceId(claim.getString("formatted")),
        )
    }

    @Test
    fun `the pairing code is read from the fragment and not from a query string`() {
        val sample = vectors.getJSONObject("claim").getString("sample")
        assertEquals(sample, Pairing.claimFromPairUrl("https://relay.example/pair#$sample"))
        assertNull(Pairing.claimFromPairUrl("https://relay.example/pair?code=$sample"))
    }

    // ── base64url ───────────────────────────────────────────────────────────

    @Test
    fun `base64url round-trips and never emits padding`() {
        for (length in 0 until 40) {
            val raw = ByteArray(length) { ((it * 37 + length) and 0xff).toByte() }
            val encoded = Pairing.b64url(raw)
            assertTrue("padding leaked at length $length", !encoded.contains('='))
            assertTrue("not url-safe at length $length", !encoded.contains('+') && !encoded.contains('/'))
            assertEquals(hex(raw), hex(Pairing.unb64url(encoded)))
        }
    }

    // ── HKDF ────────────────────────────────────────────────────────────────

    @Test
    fun `HKDF agrees with RFC 5869 test case 1`() {
        // Not our own vector — the standard's. This is what establishes that
        // every side implements the same construction rather than the same
        // mistake.
        val rfc = vectors.getJSONObject("hkdfRfc5869")
        val okm = Pairing.hkdf(
            unhex(rfc.getString("ikmHex")),
            unhex(rfc.getString("saltHex")),
            unhex(rfc.getString("infoHex")),
            rfc.getInt("length"),
        )
        assertEquals(rfc.getString("okmHex"), hex(okm))
    }

    @Test
    fun `the three keys are exactly what the device derives`() {
        val keys = vectors.getJSONObject("keys")
        val claim = keys.getString("claim")
        assertEquals(keys.getString("deviceId"), Pairing.deviceId(claim))
        assertEquals(keys.getString("accessToken"), Pairing.accessToken(claim))
        assertEquals(keys.getString("boxKeyHex"), hex(Pairing.boxKey(claim).encoded))
    }

    @Test
    fun `the three keys differ from each other`() {
        val keys = Pairing.Keys(vectors.getJSONObject("keys").getString("claim"))
        assertNotEquals(keys.deviceId, keys.accessToken)
        // The device id is what the relay logs. If it ever equalled the claim
        // code, the key to every schedule would be sitting in an access log.
        assertNotEquals(keys.deviceId, keys.claim)
        assertNotEquals(keys.accessToken, keys.claim)
    }

    // ── the envelope ────────────────────────────────────────────────────────

    @Test
    fun `a Python-sealed schedule opens here`() {
        val envelope = vectors.getJSONObject("envelope")
        val desired = envelope.getJSONObject("desired")
        val opened = Pairing.unseal(
            Pairing.boxKey(vectors.getJSONObject("keys").getString("claim")),
            envelope.getString("deviceId"),
            Pairing.SLOT_DESIRED,
            envelopeOf(desired.getJSONObject("sealed")),
        )
        assertEquals(
            desired.getJSONObject("plaintext").getString("payload"),
            JSONObject(opened).getString("payload"),
        )
    }

    @Test
    fun `a Python-sealed report opens here`() {
        val envelope = vectors.getJSONObject("envelope")
        val reported = envelope.getJSONObject("reported")
        val opened = JSONObject(
            Pairing.unseal(
                Pairing.boxKey(vectors.getJSONObject("keys").getString("claim")),
                envelope.getString("deviceId"),
                Pairing.SLOT_REPORTED,
                envelopeOf(reported.getJSONObject("sealed")),
            ),
        )
        assertEquals("Home", opened.getJSONObject("network").getString("ssid"))
        assertEquals(
            "SC1*E*1*0800*T*07",
            opened.getJSONArray("events").getJSONObject(0).getString("sc1"),
        )
    }

    @Test
    fun `a moved slot or an edited revision fails the open`() {
        // The two substitutions that matter, and both are things a relay
        // operator could do by editing a file on disk. Moving the slot plays
        // the device's own report back to it as an instruction; renumbering the
        // revision serves last month's prescription under today's number.
        val envelope = vectors.getJSONObject("envelope")
        val key = Pairing.boxKey(vectors.getJSONObject("keys").getString("claim"))
        val cases = envelope.getJSONArray("mustNotOpen")
        for (index in 0 until cases.length()) {
            val case = cases.getJSONObject(index)
            try {
                Pairing.unseal(
                    key,
                    envelope.getString("deviceId"),
                    case.getString("slot"),
                    envelopeOf(case.getJSONObject("sealed")),
                )
                fail("this must not open: ${case.getString("why")}")
            } catch (_: Pairing.SealException) {
            }
        }
    }

    @Test
    fun `an envelope sealed for one device does not open for another`() {
        val key = Pairing.boxKey(vectors.getJSONObject("keys").getString("claim"))
        val deviceId = vectors.getJSONObject("envelope").getString("deviceId")
        val sealed = Pairing.seal(key, deviceId, Pairing.SLOT_DESIRED, 1, """{"payload":"x"}""")
        try {
            Pairing.unseal(key, "some-other-device", Pairing.SLOT_DESIRED, sealed)
            fail("one household's schedule must not open on another's dispenser")
        } catch (_: Pairing.SealException) {
        }
    }

    @Test
    fun `sealing reproduces the firmware's bytes given the firmware's IV`() {
        // The strongest form of the check: not "both open each other's" but
        // "both produce the identical ciphertext". Only possible because the
        // vector pins the IV.
        val envelope = vectors.getJSONObject("envelope")
        val keys = vectors.getJSONObject("keys")
        val desired = envelope.getJSONObject("desired")
        val fromPython = desired.getJSONObject("sealed")

        val here = Pairing.sealWithIv(
            Pairing.boxKey(keys.getString("claim")),
            envelope.getString("deviceId"),
            Pairing.SLOT_DESIRED,
            desired.getInt("rev"),
            // The firmware serialises with no spaces; matching that exactly is
            // what makes the ciphertexts comparable at all.
            """{"payload":"${desired.getJSONObject("plaintext").getString("payload")}"}""",
            Pairing.unb64url(fromPython.getString("iv")),
        )

        assertEquals(fromPython.getString("iv"), here.iv)
        assertEquals(fromPython.getString("ct"), here.ct)
    }

    @Test
    fun `seal and unseal round-trip, with a fresh IV each time`() {
        val key = Pairing.boxKey(vectors.getJSONObject("keys").getString("claim"))
        val deviceId = vectors.getJSONObject("envelope").getString("deviceId")
        val payload = """{"payload":"SC1*W*1:0800.2000-127-030"}"""

        val one = Pairing.seal(key, deviceId, Pairing.SLOT_DESIRED, 42, payload)
        val two = Pairing.seal(key, deviceId, Pairing.SLOT_DESIRED, 42, payload)
        assertNotEquals(one.iv, two.iv)
        assertNotEquals(one.ct, two.ct)
        assertEquals(payload, Pairing.unseal(key, deviceId, Pairing.SLOT_DESIRED, one))
        assertEquals(12, Pairing.unb64url(one.iv).size)
    }

    @Test
    fun `the envelope serialises to what the relay expects`() {
        val envelope = Pairing.Envelope(7, "aXY", "Y3Q")
        assertEquals("""{"v":1,"rev":7,"alg":"A256GCM","iv":"aXY","ct":"Y3Q"}""", envelope.toJson())
    }

    // ── SC1*W* ──────────────────────────────────────────────────────────────

    @Test
    fun `encodeWeekly matches the firmware`() {
        val cases = vectors.getJSONArray("weekly")
        for (index in 0 until cases.length()) {
            val case = cases.getJSONObject(index)
            val slots = case.getJSONArray("slots").let { array ->
                (0 until array.length()).map { position ->
                    val item = array.getJSONObject(position)
                    val times = item.getJSONArray("times")
                    Sc1.Slot(
                        tray = item.getInt("tray"),
                        times = (0 until times.length()).map { Sc1.parseHhmm(times.getString(it))!! },
                        days = item.getInt("days"),
                        durationDays = item.getInt("durationDays"),
                    )
                }
            }
            assertEquals(case.getString("payload"), Sc1.encodeWeekly(slots))
            assertEquals(Sc1.normalise(slots), Sc1.decodeWeekly(case.getString("payload")))
        }
    }

    @Test
    fun `a schedule the device would refuse is refused here first`() {
        val bad = listOf(
            emptyList(),
            listOf(Sc1.Slot(0, listOf(480))),
            listOf(Sc1.Slot(9, listOf(480))),
            listOf(Sc1.Slot(1, emptyList())),
            listOf(Sc1.Slot(1, listOf(480, 480))),
            listOf(Sc1.Slot(1, listOf(480), days = 0)),
            listOf(Sc1.Slot(1, listOf(480), days = 128)),
            listOf(Sc1.Slot(1, listOf(480), durationDays = 1000)),
        )
        for (slots in bad) {
            try {
                Sc1.encodeWeekly(slots)
                fail("this should have been refused: $slots")
            } catch (_: Sc1.ScheduleException) {
            }
        }
    }

    @Test
    fun `times parse in every form a form field produces`() {
        assertEquals(480, Sc1.parseHhmm("08:00"))
        assertEquals(480, Sc1.parseHhmm("8:00"))
        assertEquals(480, Sc1.parseHhmm("0800"))
        assertEquals(480, Sc1.parseHhmm(" 0800 "))
        assertNull(Sc1.parseHhmm("2400"))
        assertNull(Sc1.parseHhmm("0860"))
        assertNull(Sc1.parseHhmm("nope"))
        assertEquals("0800", Sc1.formatHhmm(480))
        assertEquals("2359", Sc1.formatHhmm(1439))
    }

    @Test
    fun `day masks convert both ways`() {
        assertEquals(21, Sc1.daysToMask(listOf(0, 2, 4)))
        assertEquals("Mon, Wed, Fri", Sc1.describeDays(21))
        assertEquals("every day", Sc1.describeDays(Sc1.EVERY_DAY))
    }

    @Test
    fun `decodeWeekly refuses malformed payloads rather than guessing`() {
        assertNull(Sc1.decodeWeekly("SC1*S*1:0800"))
        assertNull(Sc1.decodeWeekly("SC1*W*1:0800-127"))
        assertNull(Sc1.decodeWeekly("SC1*W*1:0800-000-000"))
        assertNull(Sc1.decodeWeekly("nonsense"))
    }
}
